59	func TestServeIncidentsPersistAcrossKillAndDedupeRetry(t *testing.T) {
60		dataDir := t.TempDir()
61		p := startServer(t, dataDir)
62		postEvents(t, p, `{"events":[{"id":"e1","service":"gateway","severity":"critical","message":"spike","at":"2026-10-01T10:00:00Z"}]}`)
63	
64		status, created := postIncident(t, p, `{"id":"INC-1","title":" Outage ","service":"gateway","operator":"alice"}`)
65		if status != http.StatusOK || created["status"] != "open" || incNumber(created["version"]) != 1 {
66			t.Fatalf("create %d %v", status, created)
67		}
68	
69		noteBody := `{"action_id":"n1","operator":"bob","expected_version":1,"action":"add_note","content":"looking"}`
70		if status, note := postIncidentAction(t, p, "INC-1", noteBody); status != http.StatusOK || incNumber(note["version"]) != 2 {
71			t.Fatalf("note %d %v", status, note)
72		}
73		linkBody := `{"action_id":"l1","operator":"bob","expected_version":2,"action":"link_event","event_id":"e1"}`
74		if status, link := postIncidentAction(t, p, "INC-1", linkBody); status != http.StatusOK || incNumber(link["version"]) != 3 {
75			t.Fatalf("link %d %v", status, link)
76		}
77		resolveBody := `{"action_id":"r1","operator":"bob","expected_version":3,"action":"resolve","reason":"fixed"}`
78		if status, res := postIncidentAction(t, p, "INC-1", resolveBody); status != http.StatusOK || incNumber(res["version"]) != 4 {
79			t.Fatalf("resolve %d %v", status, res)
80		}
81	
82		// Hard kill; fsync had already confirmed every record.
83		p.signal(t, syscall.SIGKILL)
84		p.waitExit(t, -1)
85		waitTCPPortClosed(t, p.addr)
86	
87		p2 := startServer(t, dataDir)
88	
89		// Full snapshot recovered, including links and ordered history.
90		status, got := getIncident(t, p2, "INC-1")
91		if status != http.StatusOK {
92			t.Fatalf("get after restart %d", status)
93		}
94		if got["title"] != "Outage" || got["status"] != "resolved" || incNumber(got["version"]) != 4 {
95			t.Fatalf("recovered head %v", got)
96		}
97		linked, _ := got["events"].([]any)
98		if len(linked) != 1 || linked[0].(map[string]any)["id"] != "e1" {
99			t.Fatalf("recovered links %v", got["events"])
100		}
101		history, _ := got["history"].([]any)
102		if len(history) != 4 {
103			t.Fatalf("recovered history len %d", len(history))
104		}
105		for i, want := range []string{"create", "add_note", "link_event", "resolve"} {
106			if history[i].(map[string]any)["action"] != want {
107				t.Fatalf("history[%d]=%v want %s", i, history[i], want)
108			}
109		}
110	
111		// Retries after restart return the first results and change nothing.
112		if s, c := postIncident(t, p2, `{"id":"INC-1","title":"Outage","service":"gateway","operator":"alice"}`); s != http.StatusOK || incNumber(c["version"]) != 1 {
113			t.Fatalf("creation retry after restart %d %v", s, c)
114		}
115		if s, n := postIncidentAction(t, p2, "INC-1", noteBody); s != http.StatusOK || incNumber(n["version"]) != 2 {
116			t.Fatalf("note retry after restart %d %v", s, n)
117		}
118		if s, r := postIncidentAction(t, p2, "INC-1", resolveBody); s != http.StatusOK || incNumber(r["version"]) != 4 {
119			t.Fatalf("resolve retry after restart %d %v", s, r)
120		}
121		if _, still := getIncident(t, p2, "INC-1"); incNumber(still["version"]) != 4 {
122			t.Fatalf("retries must not advance version: %v", still["version"])
123		}
124	
125		// Continuing to operate on the recovered incident works.
126		reopenBody := `{"action_id":"o1","operator":"carol","expected_version":4,"action":"reopen","reason":"regression"}`
127		if s, o := postIncidentAction(t, p2, "INC-1", reopenBody); s != http.StatusOK || incNumber(o["version"]) != 5 {
128			t.Fatalf("reopen after restart %d %v", s, o)
129		}
130	
131		p2.signal(t, syscall.SIGTERM)
132		p2.waitExit(t, 0)
133	}
