135	func TestServeIncidentsWorkOnLegacyDataDir(t *testing.T) {
136		// An older data directory holds only events.log; incidents.log appears on
137		// first use and the recovered events can be linked.
138		dataDir := t.TempDir()
139		payload := []byte(`[{"id":"e1","service":"gateway","severity":"critical","message":"m","at":"2026-10-01T10:00:00Z"}]`)
140		frame := make([]byte, 8+len(payload))
141		binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
142		binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
143		copy(frame[8:], payload)
144		if err := os.WriteFile(filepath.Join(dataDir, "events.log"), frame, 0o644); err != nil {
145			t.Fatal(err)
146		}
