151		}
152		if status, c := postIncident(t, p, `{"id":"INC-1","title":"t","service":"gateway","operator":"alice"}`); status != http.StatusOK || incNumber(c["version"]) != 1 {
153			t.Fatalf("create on legacy dir %d %v", status, c)
154		}
155		if status, l := postIncidentAction(t, p, "INC-1",
156			`{"action_id":"l1","operator":"alice","expected_version":1,"action":"link_event","event_id":"e1"}`); status != http.StatusOK || incNumber(l["version"]) != 2 {
157			t.Fatalf("link recovered event %d %v", status, l)
158		}
159	
160		p.signal(t, syscall.SIGTERM)
161		p.waitExit(t, 0)
162		waitTCPPortClosed(t, p.addr)
