165		p2 := startServer(t, dataDir)
166		if status, got := getIncident(t, p2, "INC-1"); status != http.StatusOK || incNumber(got["version"]) != 2 {
167			t.Fatalf("incident log created in legacy dir must persist %d %v", status, got)
168		}
169		p2.signal(t, syscall.SIGTERM)
170		p2.waitExit(t, 0)
171	}
