187		payload := []byte(`{"kind":"create","at":"2026-10-01T12:00:00Z","creation":{"id":"INC-2","title":"t","service":"gateway","operator":"alice"}}`)
188		torn := make([]byte, 8+4)
189		binary.BigEndian.PutUint32(torn[0:4], uint32(len(payload)))
190		binary.BigEndian.PutUint32(torn[4:8], crc32.ChecksumIEEE(payload))
191		copy(torn[8:], payload[:4])
192		if err := os.WriteFile(path, append(existing, torn...), 0o644); err != nil {
193			t.Fatal(err)
194		}
195	
196		second := startServer(t, dataDir)
197		if status, got := getIncident(t, second, "INC-1"); status != http.StatusOK || incNumber(got["version"]) != 1 {
198			t.Fatalf("good record must survive torn tail: %d %v", status, got)
199		}
200		if status, _ := getIncident(t, second, "INC-2"); status != http.StatusNotFound {
201			t.Fatalf("torn record must be discarded: %d", status)
202		}
203		// The trimmed log accepts new durable writes.
204		if status, c := postIncident(t, second, `{"id":"INC-3","title":"t","service":"gateway","operator":"alice"}`); status != http.StatusOK || incNumber(c["version"]) != 1 {
205			t.Fatalf("create after torn tail %d %v", status, c)
206		}
