211	func TestServeFailsOnCorruptIncidentLogWithoutMutation(t *testing.T) {
212		dataDir := t.TempDir()
213		first := startServer(t, dataDir)
214		postIncident(t, first, `{"id":"INC-1","title":"t","service":"gateway","operator":"alice"}`)
215		first.signal(t, syscall.SIGKILL)
216		first.waitExit(t, -1)
217		waitTCPPortClosed(t, first.addr)
218	
219		path := filepath.Join(dataDir, "incidents.log")
220		original, err := os.ReadFile(path)
221		if err != nil {
222			t.Fatal(err)
223		}
224		firstLen := 8 + int(binary.BigEndian.Uint32(original[0:4]))
225	
226		payload := []byte(`{"kind":"create","at":"2026-10-01T12:00:00Z","creation":{"id":"INC-2","title":"t","service":"gateway","operator":"alice"}}`)
227		bad := make([]byte, 8+len(payload))
228		binary.BigEndian.PutUint32(bad[0:4], uint32(len(payload)))
229		binary.BigEndian.PutUint32(bad[4:8], crc32.ChecksumIEEE(payload))
230		copy(bad[8:], payload)
231		bad[8] ^= 0xFF // complete middle frame, bad checksum
232		corrupt := append(append([]byte{}, original[:firstLen]...), bad...)
233		if err := os.WriteFile(path, corrupt, 0o644); err != nil {
234			t.Fatal(err)
235		}
236	
237		logs := &safeBuffer{}
238		failing := exec.Command(binaryPath, "serve", "--addr", "127.0.0.1:0", "--data", dataDir)
239		failing.Stdout = logs
240		failing.Stderr = logs
241		if err := failing.Start(); err != nil {
242			t.Fatal(err)
243		}
244		done := make(chan error, 1)
245		go func() { done <- failing.Wait() }()
246		ctx, cancel := context.WithTimeout(t.Context(), 5*time.Second)
247		defer cancel()
248		select {
249		case err := <-done:
250			if err == nil {
251				t.Fatal("corrupt incident log must prevent startup")
252			}
253			if ee, ok := err.(*exec.ExitError); !ok || ee.ExitCode() == 0 {
254				t.Fatalf("corrupt incident log must exit non-zero: %v", err)
255			}
256		case <-ctx.Done():
257			failing.Process.Kill()
258			t.Fatal("server stayed up despite a corrupt incident log")
259		}
260	
261		after, err := os.ReadFile(path)
262		if err != nil {
263			t.Fatal(err)
264		}
265		if !bytes.Equal(after, corrupt) {
266			t.Fatal("failed startup must not modify the corrupt incident log")
267		}
