60	func TestReplayRebuildsState(t *testing.T) {
61		lookup := &fakeEvents{services: map[string]string{"e1": "gateway"}}
62		times := []time.Time{
63			time.Date(2026, 10, 1, 12, 0, 0, 1, time.UTC),
