70			NewCreationRecord(Creation{ID: "I1", Title: "T", Service: "gateway", Operator: "alice"}, times[0]),
71			NewActionRecord(Request{IncidentID: "I1", ActionID: "n1", Operator: "bob", ExpectedVersion: 1, Type: ActionNote, Content: "c"}, times[1]),
72			NewActionRecord(Request{IncidentID: "I1", ActionID: "l1", Operator: "bob", ExpectedVersion: 2, Type: ActionLinkEvent, Content: "e1"}, times[2]),
73			NewActionRecord(Request{IncidentID: "I1", ActionID: "r1", Operator: "bob", ExpectedVersion: 3, Type: ActionResolve, Content: "fixed"}, times[3]),
74			NewActionRecord(Request{IncidentID: "I1", ActionID: "o1", Operator: "bob", ExpectedVersion: 4, Type: ActionReopen, Content: "again"}, times[4]),
