101	
102		// After replay, an idempotent retry of a loaded action returns its first
103		// result and changes nothing.
104		replay := Request{IncidentID: "I1", ActionID: "r1", Operator: "bob", ExpectedVersion: 3, Type: ActionResolve, Content: "fixed"}
