118	func TestReplayRejectsInconsistentLog(t *testing.T) {
119		lookup := &fakeEvents{services: map[string]string{"e1": "gateway", "other": "checkout"}}
120		base := func() *Registry { return NewRegistry(lookup, nil) }
121	
122		load := func(t *testing.T, reg *Registry, records ...Record) error {
123			t.Helper()
124			for _, record := range records {
125				if err := reg.Load(record); err != nil {
126					return err
127				}
128			}
129			return nil
130		}
131		creation := func(at time.Time) Record {
132			return NewCreationRecord(Creation{ID: "I1", Title: "T", Service: "gateway", Operator: "alice"}, at)
133		}
134		t0 := time.Date(2026, 10, 1, 12, 0, 0, 0, time.UTC)
135	
136		t.Run("duplicate creation", func(t *testing.T) {
137			reg := base()
138			if err := load(t, reg, creation(t0), creation(t0.Add(time.Second))); err == nil {
139				t.Fatal("duplicate creation must fail")
140			}
141		})
142		t.Run("action for unknown incident", func(t *testing.T) {
143			reg := base()
144			act := NewActionRecord(Request{IncidentID: "ghost", ActionID: "a", Operator: "o", ExpectedVersion: 1, Type: ActionNote, Content: "c"}, t0)
145			if err := reg.Load(act); err == nil {
146				t.Fatal("action for unknown incident must fail")
147			}
148		})
149		t.Run("non sequential version", func(t *testing.T) {
150			reg := base()
151			_ = load(t, reg, creation(t0))
152			act := NewActionRecord(Request{IncidentID: "I1", ActionID: "a", Operator: "o", ExpectedVersion: 7, Type: ActionNote, Content: "c"}, t0.Add(time.Second))
153			if err := reg.Load(act); err == nil {
154				t.Fatal("gap in versions must fail")
155			}
156		})
157		t.Run("duplicate action id", func(t *testing.T) {
158			reg := base()
159			_ = load(t, reg, creation(t0))
160			act := func(ev int) Record {
161				return NewActionRecord(Request{IncidentID: "I1", ActionID: "dup", Operator: "o", ExpectedVersion: ev, Type: ActionNote, Content: "c"}, t0.Add(time.Duration(ev)*time.Second))
162			}
163			if err := reg.Load(act(1)); err != nil {
164				t.Fatal(err)
165			}
166			if err := reg.Load(act(2)); err == nil {
167				t.Fatal("reused action id must fail")
168			}
169		})
170		t.Run("linked event wrong service", func(t *testing.T) {
171			reg := base()
172			_ = load(t, reg, creation(t0))
173			act := NewActionRecord(Request{IncidentID: "I1", ActionID: "l", Operator: "o", ExpectedVersion: 1, Type: ActionLinkEvent, Content: "other"}, t0.Add(time.Second))
174			if err := reg.Load(act); err == nil {
175				t.Fatal("link to another service must fail recovery")
176			}
177		})
178		t.Run("linked event missing", func(t *testing.T) {
179			reg := base()
180			_ = load(t, reg, creation(t0))
181			act := NewActionRecord(Request{IncidentID: "I1", ActionID: "l", Operator: "o", ExpectedVersion: 1, Type: ActionLinkEvent, Content: "gone"}, t0.Add(time.Second))
182			if err := reg.Load(act); err == nil {
183				t.Fatal("link to a vanished event must fail recovery")
184			}
185		})
186		t.Run("link on resolved incident", func(t *testing.T) {
187			reg := base()
188			_ = load(t, reg, creation(t0))
189			resolve := NewActionRecord(Request{IncidentID: "I1", ActionID: "r", Operator: "o", ExpectedVersion: 1, Type: ActionResolve, Content: "done"}, t0.Add(time.Second))
190			if err := reg.Load(resolve); err != nil {
191				t.Fatal(err)
192			}
193			// Sequentially valid (expected_version 2 is current) but the incident
194			// is resolved: the shared link eligibility check must reject it.
195			link := NewActionRecord(Request{IncidentID: "I1", ActionID: "l", Operator: "o", ExpectedVersion: 2, Type: ActionLinkEvent, Content: "e1"}, t0.Add(2*time.Second))
196			if err := reg.Load(link); err == nil {
197				t.Fatal("a link on a resolved incident must fail recovery")
198			}
199		})
200		t.Run("linked event twice", func(t *testing.T) {
201			reg := base()
202			_ = load(t, reg, creation(t0))
203			first := NewActionRecord(Request{IncidentID: "I1", ActionID: "l1", Operator: "o", ExpectedVersion: 1, Type: ActionLinkEvent, Content: "e1"}, t0.Add(time.Second))
204			if err := reg.Load(first); err != nil {
205				t.Fatal(err)
206			}
207			// A fresh action id and the right expected version, but the event is
208			// already linked to this incident.
209			again := NewActionRecord(Request{IncidentID: "I1", ActionID: "l2", Operator: "o", ExpectedVersion: 2, Type: ActionLinkEvent, Content: "e1"}, t0.Add(2*time.Second))
210			if err := reg.Load(again); err == nil {
211				t.Fatal("linking the same event twice must fail recovery")
212			}
213		})
214	}
