28	func TestParticipantLifecycle(t *testing.T) {
29		reg, commit, _ := newTestRegistry(&fakeEvents{})
30		if _, err := reg.Create(validCreation()); err != nil {
31			t.Fatal(err)
32		}
33	
34		add := func(actionID string, version int, name string) {
35			t.Helper()
36			res, err := reg.Apply(Request{IncidentID: "INC-1", ActionID: actionID, Operator: "alice",
37				ExpectedVersion: version, Type: ActionAddParticipant, Content: name})
38			if err != nil {
39				t.Fatalf("add %q: %v", name, err)
40			}
41			if res.Version != version+1 {
42				t.Fatalf("add %q result version %d", name, res.Version)
43			}
44		}
45	
46		// Whitespace is trimmed, interior case kept; listing is sorted by name.
47		add("p1", 1, " Carol ")
48		add("p2", 2, "bob")
49		inc, _ := reg.Get("INC-1")
50		if !reflect.DeepEqual(inc.Participants, []string{"Alice", "Carol", "bob"}) {
51			t.Fatalf("participants sorted, case kept: %+v", inc.Participants)
52		}
53	
54		// Duplicate add is a 409-style conflict carrying the current version.
55		_, err := reg.Apply(Request{IncidentID: "INC-1", ActionID: "p3", Operator: "alice",
56			ExpectedVersion: 3, Type: ActionAddParticipant, Content: "bob"})
57		if !IsConflictError(err) || CurrentVersionOf(err) != 3 {
58			t.Fatalf("duplicate add: %v", err)
59		}
60	
61		// Names differing only in case are distinct people.
62		add("p4", 3, "Bob")
63		inc, _ = reg.Get("INC-1")
64		if !reflect.DeepEqual(inc.Participants, []string{"Alice", "Bob", "Carol", "bob"}) {
65			t.Fatalf("case-sensitive names: %+v", inc.Participants)
66		}
67	
68		// Hand ownership to a participant.
69		res, err := reg.Apply(Request{IncidentID: "INC-1", ActionID: "o1", Operator: "alice",
70			ExpectedVersion: 4, Type: ActionAssignOwner, Content: "Carol"})
71		if err != nil {
72			t.Fatalf("assign: %v", err)
73		}
74		if res.Version != 5 {
75			t.Fatalf("assign version %d", res.Version)
76		}
77		inc, _ = reg.Get("INC-1")
78		if inc.Owner != "Carol" {
79			t.Fatalf("owner after handover %q", inc.Owner)
80		}
81		// Handing over leaves the membership unchanged.
82		if !reflect.DeepEqual(inc.Participants, []string{"Alice", "Bob", "Carol", "bob"}) {
83			t.Fatalf("membership after handover: %+v", inc.Participants)
84		}
85	
86		// The current owner cannot be removed; a non-owner participant can.
87		_, err = reg.Apply(Request{IncidentID: "INC-1", ActionID: "p5", Operator: "alice",
88			ExpectedVersion: 5, Type: ActionRemoveParticipant, Content: "Carol"})
89		if !IsConflictError(err) || CurrentVersionOf(err) != 5 {
90			t.Fatalf("remove owner: %v", err)
91		}
92		if _, err := reg.Apply(Request{IncidentID: "INC-1", ActionID: "p6", Operator: "alice",
93			ExpectedVersion: 5, Type: ActionRemoveParticipant, Content: "stranger"}); !IsConflictError(err) {
94			t.Fatalf("remove non-member: %v", err)
95		}
96		if _, err := reg.Apply(Request{IncidentID: "INC-1", ActionID: "p7", Operator: "alice",
97			ExpectedVersion: 5, Type: ActionAssignOwner, Content: "stranger"}); !IsConflictError(err) {
98			t.Fatalf("assign non-member: %v", err)
99		}
100		if _, err := reg.Apply(Request{IncidentID: "INC-1", ActionID: "p8", Operator: "alice",
101			ExpectedVersion: 5, Type: ActionAssignOwner, Content: "Carol"}); !IsConflictError(err) {
102			t.Fatalf("assign current owner: %v", err)
103		}
104	
105		if _, err := reg.Apply(Request{IncidentID: "INC-1", ActionID: "p9", Operator: "alice",
106			ExpectedVersion: 5, Type: ActionRemoveParticipant, Content: "bob"}); err != nil {
107			t.Fatalf("remove member: %v", err)
108		}
109		inc, _ = reg.Get("INC-1")
110		if inc.Owner != "Carol" {
111			t.Fatalf("owner must survive removals: %q", inc.Owner)
112		}
113		if !reflect.DeepEqual(inc.Participants, []string{"Alice", "Bob", "Carol"}) {
114			t.Fatalf("membership after remove: %+v", inc.Participants)
115		}
116	
117		// Rejected actions leave version/history untouched: version moved 1->6
118		// through p1, p2, p4, o1, p9 only.
119		if inc.Version != 6 {
120			t.Fatalf("version after accepted actions %d", inc.Version)
121		}
122		if len(inc.History) != 6 {
123			t.Fatalf("history after accepted actions %d", len(inc.History))
124		}
125		if commit.count() != 6 {
126			t.Fatalf("durable records %d", commit.count())
127		}
