196	func TestPersonnelActionReplayAcrossChanges(t *testing.T) {
197		reg, _, _ := newTestRegistry(&fakeEvents{})
198		_, _ = reg.Create(validCreation())
199	
200		// Add Carol, add Eve, hand ownership to Eve, remove Carol, resolve.
201		first := Request{IncidentID: "INC-1", ActionID: "p1", Operator: "alice",
202			ExpectedVersion: 1, Type: ActionAddParticipant, Content: "Carol"}
203		res, err := reg.Apply(first)
204		if err != nil {
205			t.Fatal(err)
206		}
207		must := func(req Request) {
208			t.Helper()
209			if _, err := reg.Apply(req); err != nil {
210				t.Fatal(err)
211			}
212		}
213		must(Request{IncidentID: "INC-1", ActionID: "p2", Operator: "alice",
214			ExpectedVersion: 2, Type: ActionAddParticipant, Content: "Eve"})
215		must(Request{IncidentID: "INC-1", ActionID: "o1", Operator: "alice",
216			ExpectedVersion: 3, Type: ActionAssignOwner, Content: "Eve"})
217		must(Request{IncidentID: "INC-1", ActionID: "p3", Operator: "eve",
218			ExpectedVersion: 4, Type: ActionRemoveParticipant, Content: "Carol"})
219		must(Request{IncidentID: "INC-1", ActionID: "r1", Operator: "eve",
220			ExpectedVersion: 5, Type: ActionResolve, Content: "done"})
221	
222		// Even with the incident resolved and Carol long removed, retrying the
223		// original add returns its first result and restores nothing: Carol stays
224		// absent, Eve stays owner, and the version does not move.
225		replay, err := reg.Apply(first)
226		if err != nil {
227			t.Fatalf("replay: %v", err)
228		}
229		if replay != res {
230			t.Fatalf("replay %+v want %+v", replay, res)
231		}
232		inc, _ := reg.Get("INC-1")
233		if inc.Version != 6 {
234			t.Fatalf("replay must not advance version: %d", inc.Version)
235		}
236		if !reflect.DeepEqual(inc.Participants, []string{"Alice", "Eve"}) {
237			t.Fatalf("replay must not restore membership: %+v", inc.Participants)
238		}
239		if inc.Owner != "Eve" {
240			t.Fatalf("replay must not touch owner: %q", inc.Owner)
241		}
242	
243		// Same action id with changed content is a conflict even after resolution.
244		_, err = reg.Apply(Request{IncidentID: "INC-1", ActionID: "p1", Operator: "alice",
245			ExpectedVersion: 6, Type: ActionAddParticipant, Content: "Dave"})
246		if !IsConflictError(err) {
247			t.Fatalf("changed replay: %v", err)
248		}
249	}
