20		"testing"
21		"time"
22	)
23	
24	var (
25		binaryPath string
26		buildOnce  sync.Once
27		buildErr   error
28	)
29	
30	func TestMain(m *testing.M) {
31		buildOnce.Do(func() {
32			dir, err := os.MkdirTemp("", "signalroom-build-")
33			if err != nil {
34				buildErr = err
35				return
36			}
37			binaryPath = filepath.Join(dir, "signalroom")
38			buildErr = exec.Command("go", "build", "-o", binaryPath, ".").Run()
39		})
40		if buildErr != nil {
41			fmt.Fprintln(os.Stderr, "build test binary:", buildErr)
42			os.Exit(1)
43		}
44		os.Exit(m.Run())
45	}
46	
47	type serverProc struct {
48		cmd    *exec.Cmd
49		addr   string
50		logs   *safeBuffer
51		waitCh chan error
52		done   chan struct{}
53	}
54	
55	func (p *serverProc) exited() bool {
56		select {
57		case <-p.done:
58			return true
59		default:
60			return false
61		}
62	}
63	
64	type safeBuffer struct {
65		mu  sync.Mutex
66		buf bytes.Buffer
67	}
68	
69	func (s *safeBuffer) Write(p []byte) (int, error) {
70		s.mu.Lock()
71		defer s.mu.Unlock()
72		return s.buf.Write(p)
73	}
74	
75	func (s *safeBuffer) String() string {
76		s.mu.Lock()
77		defer s.mu.Unlock()
78		return s.buf.String()
79	}
80	
81	// startServer launches serve on an ephemeral port and blocks until the
82	// readiness line publishes the real address — no fixed sleeps.
83	func startServer(t *testing.T, dataDir string) *serverProc {
84		t.Helper()
85		logs := &safeBuffer{}
86		cmd := exec.Command(binaryPath, "serve", "--addr", "127.0.0.1:0", "--data", dataDir)
87		stdout, err := cmd.StdoutPipe()
88		if err != nil {
89			t.Fatal(err)
90		}
91		stderr, err := cmd.StderrPipe()
92		if err != nil {
93			t.Fatal(err)
94		}
95		if err := cmd.Start(); err != nil {
96			t.Fatalf("start serve: %v", err)
97		}
98		waitCh := make(chan error, 1)
99		done := make(chan struct{})
100		go func() {
101			waitCh <- cmd.Wait()
102			close(done)
103		}()
104	
105		ready := make(chan string, 1)
106		scan := func(r io.Reader) {
107			scanner := bufio.NewScanner(r)
108			for scanner.Scan() {
109				line := scanner.Text()
110				logs.Write([]byte(line + "\n"))
111				if addr, ok := strings.CutPrefix(line, "signalroom: listening on "); ok {
112					select {
113					case ready <- strings.TrimSpace(addr):
114					default:
115					}
116				}
117			}
118		}
119		go scan(stdout)
120		go scan(stderr)
121	
122		select {
123		case addr := <-ready:
124			proc := &serverProc{cmd: cmd, addr: addr, logs: logs, waitCh: waitCh, done: done}
125			t.Cleanup(func() { proc.killIfAlive() })
126			return proc
127		case err := <-waitCh:
128			t.Fatalf("serve exited before becoming ready (%v); output:\n%s", err, logs.String())
129			return nil
130		case <-time.After(5 * time.Second):
131			t.Fatalf("server never became ready; output:\n%s", logs.String())
132			return nil
133		}
134	}
