1	package logfile
2	
3	import (
4		"encoding/binary"
5		"errors"
6		"fmt"
7		"hash/crc32"
8		"os"
9		"path/filepath"
10		"sync"
11	)
12	
13	const (
14		headerSize = 8
15		// MaxPayloadBytes is the 64 MiB (1024*1024-byte units) capacity of one
16		// frame payload. It bounds the saved content itself, excluding the
17		// 8-byte frame header, and guards against absurd allocations when a
18		// corrupt length prefix happens to point inside the file.
19		MaxPayloadBytes = 64 << 20
20	)
21	
22	// ErrPayloadTooLarge is returned when a frame's encoded content exceeds
23	// MaxPayloadBytes. It describes the content, not a storage fault: the check
24	// runs before anything is written or locked for mutation, the log is not
25	// poisoned, and later writes keep working without a restart.
26	var ErrPayloadTooLarge = errors.New("frame payload exceeds the 64 MiB save capacity")
27	
28	// ErrPoisoned is returned after a write or sync failure. The log refuses all
29	// further writes until the process is restarted and recovery succeeds.
30	var ErrPoisoned = errors.New("log is unavailable after a storage failure")
31	
32	// CorruptionError marks a complete frame that fails its checksum or contains
33	// illegal data, as opposed to an incomplete trailing frame.
34	type CorruptionError struct{ Reason string }
35	
36	func (e *CorruptionError) Error() string { return e.Reason }
37	
38	func corruption(format string, args ...any) error {
