56	// openFrameLog opens (creating if absent) the named log inside an
57	// already-locked data directory, replays its frames with decode, and
58	// truncates at most one incomplete trailing frame. A corrupt frame in the
59	// middle, or a complete frame whose payload decode rejects, is fatal and
60	// leaves the file untouched. When check is non-nil it validates the
61	// recovered items after replay and before any truncation, so a rejection
62	// there is also fatal without modifying a single byte of the file.
63	func openFrameLog[T any](dir, name, noun, unit string, decode func(payload []byte) (T, error), check func(items []T) error) (*frameLog, []T, error) {
64		path := filepath.Join(dir, name)
65		file, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|os.O_APPEND, 0o644)
66		if err != nil {
67			return nil, nil, fmt.Errorf("open %s log: %w", noun, err)
68		}
69	
70		items, validLen, err := replayFrames(file, noun, decode)
71		if err != nil {
72			file.Close()
73			return nil, nil, err
74		}
75		if check != nil {
76			if err := check(items); err != nil {
77				file.Close()
78				return nil, nil, err
79			}
80		}
81		if info, statErr := file.Stat(); statErr == nil && validLen < info.Size() {
82			// Drop exactly one incomplete trailing frame; the only mutation
83			// recovery performs, fsynced before serving.
84			if err := file.Truncate(validLen); err != nil {
85				file.Close()
86				return nil, nil, fmt.Errorf("truncate incomplete trailing %s frame: %w", noun, err)
87			}
88			if err := file.Sync(); err != nil {
89				file.Close()
90				return nil, nil, fmt.Errorf("sync %s log: %w", noun, err)
91			}
92		}
93		// Flush the directory so the log file's own entry is durable, whether it
94		// was just created or just truncated.
95		if err := syncDir(dir); err != nil {
96			file.Close()
97			return nil, nil, fmt.Errorf("sync data directory: %w", err)
98		}
99	
100		return &frameLog{file: file, dir: dir, noun: noun, unit: unit}, items, nil
101	}
102	
103	// replayFrames scans the log and returns the decoded frames and the byte
104	// offset at which the log is known good. A torn trailing frame — a partial
105	// header, or a header whose payload never fully landed — ends the scan
106	// without error; any corruption before that offset is fatal.
107	func replayFrames[T any](file *os.File, noun string, decode func(payload []byte) (T, error)) ([]T, int64, error) {
108		data, err := os.ReadFile(file.Name())
109		if err != nil {
110			return nil, 0, fmt.Errorf("read %s log: %w", noun, err)
111		}
112	
113		var items []T
114		pos := int64(0)
115		for pos < int64(len(data)) {
116			remaining := int64(len(data)) - pos
117			if remaining < headerSize {
118				break // torn partial header
119			}
120			payloadLen := int64(binary.BigEndian.Uint32(data[pos : pos+4]))
121			if payloadLen <= 0 || payloadLen > MaxPayloadBytes {
122				return nil, 0, corruption("corrupt %s frame header at offset %d", noun, pos)
123			}
124			frameEnd := pos + headerSize + payloadLen
125			if frameEnd > int64(len(data)) {
126				break // header landed but its payload did not: torn tail
127			}
128			payload := data[pos+headerSize : frameEnd]
129			wantCRC := binary.BigEndian.Uint32(data[pos+4 : pos+headerSize])
130			if crc32.ChecksumIEEE(payload) != wantCRC {
131				return nil, 0, corruption("%s checksum mismatch at offset %d", noun, pos)
132			}
133			item, err := decode(payload)
134			if err != nil {
135				return nil, 0, corruption("illegal %s frame payload at offset %d: %v", noun, pos, err)
136			}
