143	// appendFrame durably writes one already-encoded payload: the frame is
144	// written and fsynced before the call returns. Any write or sync failure
145	// poisons the log, so this call and every later one fail until restart. A
146	// payload that fails the size check returns ErrPayloadTooLarge before the
147	// log is touched and does not poison it.
148	func (l *frameLog) appendFrame(payload []byte) (err error) {
149		if len(payload) > MaxPayloadBytes {
150			return fmt.Errorf("%w: %s is %d bytes", ErrPayloadTooLarge, l.unit, len(payload))
151		}
152	
153		frame := make([]byte, headerSize+len(payload))
154		binary.BigEndian.PutUint32(frame[0:4], uint32(len(payload)))
155		binary.BigEndian.PutUint32(frame[4:8], crc32.ChecksumIEEE(payload))
156		copy(frame[headerSize:], payload)
157	
158		l.mu.Lock()
159		defer l.mu.Unlock()
160		if l.poisoned {
161			return ErrPoisoned
162		}
163		defer func() {
164			if err != nil {
165				l.poisoned = true
166			}
167		}()
168	
169		if _, err = l.file.Write(frame); err != nil {
170			return fmt.Errorf("write %s log: %w", l.noun, err)
171		}
172		if err = l.file.Sync(); err != nil {
173			return fmt.Errorf("sync %s log: %w", l.noun, err)
174		}
175		return nil
176	}
177	
178	// Poisoned reports whether the log has suffered an unrecoverable write error.
179	func (l *frameLog) Poisoned() bool {
180		l.mu.Lock()
181		defer l.mu.Unlock()
182		return l.poisoned
183	}
184	
185	// Close releases the log file.
186	func (l *frameLog) Close() error {
187		l.mu.Lock()
