216	
217		// Reopen, then a note works again.
218		_, err = reg.Apply(Request{IncidentID: "INC-1", ActionID: "o1", Operator: "bob", ExpectedVersion: 4, Type: ActionReopen, Content: "regression"})
219		if err != nil {
