378	func TestConcurrentSameVersionOnlyOneSucceeds(t *testing.T) {
379		reg, commit, _ := newTestRegistry(&fakeEvents{})
380		_, _ = reg.Create(validCreation())
381	
382		// Distinct action ids all racing at version 1: exactly one commits.
383		const n = 32
384		var wg sync.WaitGroup
385		var successes int64
386		var mu sync.Mutex
387		start := make(chan struct{})
388		for i := 0; i < n; i++ {
389			wg.Add(1)
390			go func(i int) {
391				defer wg.Done()
392				<-start
393				req := Request{IncidentID: "INC-1", ActionID: "race" + strconv.Itoa(i),
394					Operator: "o", ExpectedVersion: 1, Type: ActionNote, Content: "c"}
395				if _, err := reg.Apply(req); err == nil {
396					mu.Lock()
397					successes++
398					mu.Unlock()
