529		// expected_version matches (2), so only the resolved state and the
530		// missing event are in play; the state conflict must be reported.
531		_, err := reg.Apply(Request{IncidentID: "INC-1", ActionID: "l1", Operator: "b",
532			ExpectedVersion: 2, Type: ActionLinkEvent, Content: "ghost"})
533		if !IsConflictError(err) || CurrentVersionOf(err) != 2 {
534			t.Fatalf("resolved status must win over the missing event, got %v", err)
535		}
536		if IsNotFoundError(err) {
537			t.Fatalf("missing event must not be reported on a resolved incident: %v", err)
538		}
539		inc, _ := reg.Get("INC-1")
540		if inc.Status != StatusResolved || inc.Version != 2 || len(inc.Links) != 0 {
541			t.Fatalf("rejected link must change nothing: %+v", inc)
