548	// A committed link replays idempotently even after the incident has moved on
549	// and resolved: the first result comes back verbatim and nothing is added.
550	func TestLinkIdempotentReplayAcrossResolution(t *testing.T) {
551		lookup := &fakeEvents{services: map[string]string{"e1": "gateway", "e2": "gateway"}}
552		reg, commit, _ := newTestRegistry(lookup)
553		_, _ = reg.Create(validCreation())
554	
555		first := Request{IncidentID: "INC-1", ActionID: "l1", Operator: "bob",
556			ExpectedVersion: 1, Type: ActionLinkEvent, Content: "e1"}
557		res, err := reg.Apply(first)
558		if err != nil {
559			t.Fatal(err)
560		}
561		if res != (ActionResult{IncidentID: "INC-1", ActionID: "l1", Version: 2}) {
562			t.Fatalf("first link result %+v", res)
563		}
564		if _, err := reg.Apply(Request{IncidentID: "INC-1", ActionID: "r1", Operator: "bob",
565			ExpectedVersion: 2, Type: ActionResolve, Content: "done"}); err != nil {
566			t.Fatal(err)
567		}
568	
569		// Same action id and same normalized content, now stale and resolved:
570		// still the first result, still no extra link or history entry.
571		replay, err := reg.Apply(first)
572		if err != nil {
573			t.Fatalf("replay after resolution: %v", err)
574		}
575		if replay != res {
576			t.Fatalf("replay %+v want %+v", replay, res)
577		}
578		inc, _ := reg.Get("INC-1")
579		if inc.Version != 3 || len(inc.History) != 3 || len(inc.Links) != 1 {
580			t.Fatalf("replay must add nothing: %+v", inc)
581		}
582		if inc.Links[0] != "e1" {
583			t.Fatalf("links must be untouched: %+v", inc.Links)
584		}
585		if commit.count() != 3 { // create + link + resolve
586			t.Fatalf("replay must not persist, count=%d", commit.count())
587		}
588	
589		// The same action id with changed content stays a conflict.
590		_, err = reg.Apply(Request{IncidentID: "INC-1", ActionID: "l1", Operator: "bob",
591			ExpectedVersion: 3, Type: ActionLinkEvent, Content: "e2"})
592		if !IsConflictError(err) {
593			t.Fatalf("changed link content: want conflict, got %v", err)
594		}
595		if got := CurrentVersionOf(err); got != 3 {
596			t.Fatalf("changed-content conflict reports version %d, want 3", got)
597		}
598	}
